using System.Linq;
using Autodesk.Revit.DB;
using Autodesk.Revit.DB.Electrical;

var doc = Document;
// setup: a cable tray type and the lowest level (Create takes the TYPE first, then points, then level)
var trayType = new FilteredElementCollector(doc).OfClass(typeof(CableTrayType)).Cast<CableTrayType>().First();
var level = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().OrderBy(l => l.Elevation).First();
var start = new XYZ(0, 15, 9);
var end   = new XYZ(20, 15, 9);

ElementId id = null;
Connector.WithTransaction(doc, () => {
    var t = CableTray.Create(doc, trayType.Id, start, end, level.Id);
    id = t.Id;
});

var created = (CableTray)doc.GetElement(id);
var length = created.get_Parameter(BuiltInParameter.CURVE_ELEM_LENGTH)?.AsDouble();
return new { id = id.ToString(), trayType = trayType.Name, level = level.Name, lengthFeet = length };
